				},
			},
		],
	} // 设置配置项

	chartInstance.setOption(option) // 绑定点击事件

	chartInstance.on('click', (params) => {
		activeWord.value = params.data
	}) // 监听窗口大小变化，自动调整图表

	const handleResize = () => {
